WITH lines AS (SELECT id, customer_id, pos, item.product_id, item.qty, item.price, item.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) li AS pos, item) SELECT CASE WHEN price >= 245 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, MAX(qty) AS max_qty, ROUND(SUM(pos) / NULLIF(COUNT(CASE WHEN promo = 'VIP' THEN 1 END), 0), 2) AS pos_per_vip, COUNT(*) FILTER (WHERE promo = 'SPRING10') AS spring10_rows, COUNT(*) AS num_rows FROM lines GROUP BY CUBE (CASE WHEN price >= 245 THEN 'PREMIUM' ELSE 'STANDARD' END);
